foreach($files as $path=>$f){$target=$root.'/'.$path;ensure(copy($target,$backup.'/'.str_replace('/','_',$path)),'file_backup');$tmp=$target.'.next';ensure(!file_exists($tmp),'staged_exists');ensure(file_put_contents($tmp,base64_decode($f['data'],true))!==false,'write');chmod($tmp,0600);$output=[];$code=1;exec(escapeshellarg(PHP_BINARY).' -l '.escapeshellarg($tmp).' 2>&1',$output,$code);ensure($code===0,'syntax');}
